#!/bin/sh
# PanelComfort scheduler for rooted LG webOS TVs. Uses only BusyBox/POSIX tools + luna-send.
set -u
ROOT_DIR=/var/lib/webosbrew/panelcomfort
CFG="$ROOT_DIR/config.env"
LOG="$ROOT_DIR/service.log"
[ -r "$CFG" ] || exit 0
# Config is generated by the app using validated values, not arbitrary shell input.

log(){ printf '%s %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$*" >> "$LOG"; }
APPLY_LOCK="$ROOT_DIR/apply.lock"
acquire_apply_lock(){
  tries=0
  while ! mkdir "$APPLY_LOCK" 2>/dev/null; do
    owner=$(cat "$APPLY_LOCK/pid" 2>/dev/null || true)
    case "$owner" in
      ''|*[!0-9]*) ;;
      *)
        if ! kill -0 "$owner" 2>/dev/null; then rm -rf "$APPLY_LOCK" 2>/dev/null || true
        elif [ -r "/proc/$owner/cmdline" ] && ! tr '\000' ' ' < "/proc/$owner/cmdline" 2>/dev/null | grep -q 'daemon.sh'; then rm -rf "$APPLY_LOCK" 2>/dev/null || true
        fi ;;
    esac
    tries=$((tries + 1))
    [ "$tries" -lt 150 ] || return 1
    sleep 0.1
  done
  printf '%s\n' "$$" > "$APPLY_LOCK/pid"
}
release_apply_lock(){
  [ "$(cat "$APPLY_LOCK/pid" 2>/dev/null || true)" = "$$" ] || return 0
  rm -f "$APPLY_LOCK/pid"
  rmdir "$APPLY_LOCK" 2>/dev/null || true
}
# Use arithmetic without non-POSIX base prefixes (BusyBox ash compatibility).
parse_time(){ hh="${1%:*}"; mm="${1#*:}"; echo $(( ${hh#0} * 60 + ${mm#0} )); }
norm(){ n=$1; while [ "$n" -lt 0 ]; do n=$((n+1440)); done; while [ "$n" -ge 1440 ]; do n=$((n-1440)); done; echo "$n"; }
elapsed(){ echo $(( ($1 - $2 + 1440) % 1440 )); }
in_cyclic_range(){ # current, start, end; half-open; equal endpoints mean empty
  cur=$1; st=$2; en=$3
  [ "$st" -eq "$en" ] && return 1
  if [ "$st" -lt "$en" ]; then [ "$cur" -ge "$st" ] && [ "$cur" -lt "$en" ]; else [ "$cur" -ge "$st" ] || [ "$cur" -lt "$en" ]; fi
}
sun_event_minute(){
  event=$1
  [ -n "${SUNSET_LAT:-}" ] && [ -n "${SUNSET_LON:-}" ] || return 1
  doy=$(date +%j); offset=$(date +%z)
  case "$event" in sunrise) event_hour=6;; sunset) event_hour=18;; *) return 1;; esac
  awk -v n="$doy" -v lat="$SUNSET_LAT" -v lon="$SUNSET_LON" -v tz="$offset" -v event="$event" -v eventHour="$event_hour" 'BEGIN {
    pi=atan2(0,-1); rad=pi/180;
    sign=substr(tz,1,1); hh=substr(tz,2,2)+0; mm=substr(tz,4,2)+0; tzmin=hh*60+mm; if(sign=="-")tzmin=-tzmin;
    lngHour=lon/15; t=n+((eventHour-lngHour)/24); M=0.9856*t-3.289;
    L=M+1.916*sin(M*rad)+0.020*sin(2*M*rad)+282.634; L=L-360*int(L/360); if(L<0)L+=360;
    RA=atan2(0.91764*(sin(L*rad)/cos(L*rad)),1)*180/pi; RA=RA-360*int(RA/360); if(RA<0)RA+=360;
    Lq=90*int(L/90); RAq=90*int(RA/90); RA=(RA+(Lq-RAq))/15;
    sinDec=0.39782*sin(L*rad); cosDec=sqrt(1-sinDec*sinDec);
    den=cosDec*cos(lat*rad); if(den==0) exit 2;
    cosH=(cos(90.833*rad)-sinDec*sin(lat*rad))/den; if(cosH>1 || cosH< -1) exit 2;
    H=atan2(sqrt(1-cosH*cosH),cosH)/rad/15; if(event=="sunrise")H=24-H;
    T=H+RA-0.06571*t-6.622; UT=T-lngHour; UT=UT-24*int(UT/24); if(UT<0)UT+=24;
    local=int(UT*60+0.5)+tzmin; local=local-1440*int(local/1440); if(local<0)local+=1440;
    printf "%d\n",local;
  }'
}
sunset_minute(){ sun_event_minute sunset; }
sunrise_minute(){ sun_event_minute sunrise; }
sun_altitude(){
  [ -n "${SUNSET_LAT:-}" ] && [ -n "${SUNSET_LON:-}" ] || return 1
  doy=$(date +%j); clock=$(parse_time "$(date +%H:%M)"); tz=$(date +%z)
  awk -v n="$doy" -v clock="$clock" -v lat="$SUNSET_LAT" -v lon="$SUNSET_LON" -v tz="$tz" 'BEGIN {
    pi=atan2(0,-1); rad=pi/180;
    sign=substr(tz,1,1); hh=substr(tz,2,2)+0; mm=substr(tz,4,2)+0; tzmin=hh*60+mm; if(sign=="-")tzmin=-tzmin;
    B=2*pi*(n-81)/364; eot=9.87*sin(2*B)-7.53*cos(B)-1.5*sin(B);
    decl=23.44*sin(2*pi*(284+n)/365);
    solarMin=clock+eot+4*lon-tzmin; hourAngle=(solarMin/4)-180; ha=hourAngle*rad;
    x=sin(lat*rad)*sin(decl*rad)+cos(lat*rad)*cos(decl*rad)*cos(ha);
    if(x>1)x=1;if(x< -1)x=-1;
    alt=atan2(x,sqrt(1-x*x))/rad; printf "%.3f\n",alt;
  }'
}
curve_percent(){ # elapsed minutes, duration minutes, curve => 0..100 progress
  awk -v e="$1" -v d="$2" -v c="${3:-smooth}" 'BEGIN {
    if(d<=0){print 100;exit};x=e/d;if(x<0)x=0;if(x>1)x=1;pi=atan2(0,-1);
    if(c=="easein") y=x*x;
    else if(c=="easeout") y=1-(1-x)*(1-x);
    else if(c=="smooth") y=x*x*(3-2*x);
    else if(c=="smootherstep") y=x*x*x*(x*(x*6-15)+10);
    else if(c=="twilight") y=0.5-0.5*cos(pi*x);
    else if(c=="rolloff-soft") y=log(1+4*x)/log(5);
    else if(c=="rolloff") y=log(1+9*x)/log(10);
    else if(c=="rolloff-strong") y=log(1+19*x)/log(20);
    else if(c=="exponential") y=(exp(4*x)-1)/(exp(4)-1);
    else if(c=="gamma-late") y=x^2.2;
    else if(c=="gamma-early") y=x^0.4545454545;
    else y=x;
    printf "%d\n",int(y*100+0.5);
  }'
}
# Query the model-dependent LG TV ambient/luminance sensor. Streaming subscriptions
# commonly send an initial backlight reply followed by sensorData, so take any
# luminance value returned during a short bounded subscription window.
tv_sensor_luminance(){
  command -v luna-send >/dev/null 2>&1 || return 1
  if command -v timeout >/dev/null 2>&1; then
    response=$(timeout 3 luna-send -i -f 'luna://com.webos.service.pqcontroller/getEyeqSensorData' '{"subscribe":true}' 2>/dev/null || true)
  elif command -v busybox >/dev/null 2>&1 && busybox timeout --help >/dev/null 2>&1; then
    response=$(busybox timeout 3 luna-send -i -f 'luna://com.webos.service.pqcontroller/getEyeqSensorData' '{"subscribe":true}' 2>/dev/null || true)
  else
    return 1
  fi
  value=$(printf '%s\n' "$response" | sed -n 's/.*"luminance"[[:space:]]*:[[:space:]]*\([0-9][0-9]*\).*/\1/p' | tail -n 1)
  [ -n "$value" ] || value=$(printf '%s\n' "$response" | sed -n 's/.*"visibleLuminance"[[:space:]]*:[[:space:]]*\([0-9][0-9]*\).*/\1/p' | tail -n 1)
  case "$value" in ''|*[!0-9]*) return 1;; esac
  [ "$value" -le 200000 ] 2>/dev/null || return 1
  printf '%s\n' "$value"
}
cached_tv_sensor_luminance(){
  status_file="$ROOT_DIR/tv-sensor-status"
  [ -r "$status_file" ] || return 1
  value=$(sed -n 's/^TV_SENSOR_LUMINANCE=//p' "$status_file" | tail -n 1)
  stamp=$(sed -n 's/^TV_SENSOR_UPDATED=//p' "$status_file" | tail -n 1)
  now=$(date +%s)
  case "$value:$stamp" in *[!0-9:]*|:*) return 1;; esac
  [ "$stamp" -gt 0 ] 2>/dev/null && [ $((now-stamp)) -ge 0 ] && [ $((now-stamp)) -le 180 ] || return 1
  [ "$value" -le 200000 ] 2>/dev/null || return 1
  printf '%s\n' "$value"
}
write_tv_sensor_status(){
  available=$1; value=${2:-}; stamp=$(date +%s)
  { printf 'TV_SENSOR_AVAILABLE=%s\n' "$available"; printf 'TV_SENSOR_LUMINANCE=%s\n' "$value"; printf 'TV_SENSOR_UPDATED=%s\n' "$stamp"; } > "$ROOT_DIR/tv-sensor-status.tmp" && mv "$ROOT_DIR/tv-sensor-status.tmp" "$ROOT_DIR/tv-sensor-status"
}

calculate(){
  now=$(parse_time "$(date +%H:%M)")
  # HA refreshes unchanged lux once per minute. Require data to be recent and
  # received after this scheduler session began; missing/stale data uses time.
  haLux=${HA_AMBIENT_LUX:-}; haLuxStamp=${HA_AMBIENT_LUX_UPDATED:-0}; stampNow=$(date +%s)
  case "$haLux" in ''|*[!0-9]*) haLux='';; esac
  case "$haLuxStamp" in ''|*[!0-9]*) haLuxStamp=0;; esac
  haLuxSessionStart=0
  if [ -r "$ROOT_DIR/lux-session-start" ]; then haLuxSessionStart=$(cat "$ROOT_DIR/lux-session-start" 2>/dev/null || echo 0); fi
  case "$haLuxSessionStart" in ''|*[!0-9]*) haLuxSessionStart=0;; esac
  haLuxFresh=0
  if [ -n "$haLux" ] && [ "$haLux" -le 200000 ] 2>/dev/null && [ "$haLuxStamp" -gt "$haLuxSessionStart" ] 2>/dev/null && [ $((stampNow-haLuxStamp)) -ge 0 ] && [ $((stampNow-haLuxStamp)) -le 120 ]; then
    haLuxFresh=1
  fi
  max=${MAX_BRIGHTNESS:-80}; min=${MIN_BRIGHTNESS:-18};
  [ "$min" -lt 0 ] && min=0; [ "$min" -gt 100 ] && min=100; [ "$max" -lt 0 ] && max=0; [ "$max" -gt 100 ] && max=100
  hdrMax=${HYPERHDR_MAX_BRIGHTNESS:-60}; hdrMin=${HYPERHDR_MIN_BRIGHTNESS:-12}
  [ "$hdrMin" -lt 0 ] && hdrMin=0; [ "$hdrMin" -gt 100 ] && hdrMin=100; [ "$hdrMax" -lt 0 ] && hdrMax=0; [ "$hdrMax" -gt 100 ] && hdrMax=100
  [ "$hdrMin" -gt "$hdrMax" ] && hdrMin=$hdrMax
  dimStart=$(parse_time "${DIM_START:-21:00}")
  if [ "${DIM_MODE:-fixed}" = sunset ]; then
    sun=$(sunset_minute 2>/dev/null || true)
    if [ -n "$sun" ]; then dimStart=$(norm $((sun + ${SUNSET_OFFSET:--20}))); else log 'Sunset calculation unavailable; using configured fixed dim-start time'; fi
  fi
  upStart=$(parse_time "${UNDIM_START:-06:30}")
  if [ "${UP_MODE:-fixed}" = sunrise ]; then
    sun=$(sunrise_minute 2>/dev/null || true)
    if [ -n "$sun" ]; then upStart=$(norm $((sun + ${SUNRISE_OFFSET:-0}))); else log 'Sunrise calculation unavailable; using configured fixed morning start'; fi
  fi
  dimDur=${DIM_DURATION:-60}; upDur=${UNDIM_DURATION:-45}; curve=${FADE_CURVE:-smooth}; fadeMethod=${FADE_METHOD:-duration}
  [ "$dimDur" -lt 0 ] && dimDur=0; [ "$dimDur" -gt 720 ] && dimDur=720; [ "$upDur" -lt 0 ] && upDur=0; [ "$upDur" -gt 720 ] && upDur=720
  dimEnd=$(norm $((dimStart + dimDur))); upEnd=$(norm $((upStart + upDur)))
  brightness=$max; hdrBrightness=$hdrMax; phase=day
  if [ -f "$ROOT_DIR/override.flag" ]; then
    if [ "${MOVIE_BRIGHTNESS_ENABLED:-0}" = 1 ]; then
      movieBrightness=${MOVIE_BRIGHTNESS:-$max}
      case "$movieBrightness" in ''|*[!0-9]*) movieBrightness=$max;; esac
      [ "$movieBrightness" -lt 0 ] && movieBrightness=0
      [ "$movieBrightness" -gt 100 ] && movieBrightness=100
      brightness=$movieBrightness
      # Treat the slider as the TV's actual percentage. Map its position
      # within the TV's configured night/day range into HyperHDR's own range,
      # so both outputs reach their configured endpoints together.
      tvRange=$((max-min)); hdrRange=$((hdrMax-hdrMin))
      if [ "$tvRange" -gt 0 ]; then
        moviePosition=$(((movieBrightness-min)*1000/tvRange))
        [ "$moviePosition" -lt 0 ] && moviePosition=0
        [ "$moviePosition" -gt 1000 ] && moviePosition=1000
        hdrBrightness=$((hdrMin + (hdrRange*moviePosition+500)/1000))
      elif [ "$movieBrightness" -ge "$max" ]; then hdrBrightness=$hdrMax
      else hdrBrightness=$hdrMin
      fi
    else
      brightness=$max; hdrBrightness=$hdrMax
    fi
    phase=movie-override
  elif [ "${ENABLED:-1}" != 1 ]; then
    brightness=$max; hdrBrightness=$hdrMax; phase=disabled
  else
    # Solar-elevation mode uses coordinates directly; fade duration is not used.
    if [ "$fadeMethod" = solar ]; then
      if [ -n "${SUNSET_LAT:-}" ] && [ -n "${SUNSET_LON:-}" ]; then
        altitude=$(sun_altitude 2>/dev/null || true)
        if [ -n "$altitude" ]; then
          pct=$(awk -v a="$altitude" -v c="$curve" 'BEGIN { if(a>=4){x=0}else if(a<=-8){x=1}else{x=(4-a)/12};pi=atan2(0,-1);if(c=="easein")x=x*x;else if(c=="easeout")x=1-(1-x)*(1-x);else if(c=="smooth")x=x*x*(3-2*x);else if(c=="smootherstep")x=x*x*x*(x*(x*6-15)+10);else if(c=="twilight")x=0.5-0.5*cos(pi*x);else if(c=="rolloff-soft")x=log(1+4*x)/log(5);else if(c=="rolloff")x=log(1+9*x)/log(10);else if(c=="rolloff-strong")x=log(1+19*x)/log(20);else if(c=="exponential")x=(exp(4*x)-1)/(exp(4)-1);else if(c=="gamma-late")x=x^2.2;else if(c=="gamma-early")x=x^0.4545454545;printf "%d\n",int(x*100+0.5) }')
          [ "$pct" -lt 0 ] && pct=0; [ "$pct" -gt 100 ] && pct=100
          brightness=$((max - (max-min)*pct/100)); hdrBrightness=$((hdrMax - (hdrMax-hdrMin)*pct/100))
          if awk -v a="$altitude" 'BEGIN{exit !(a>=4)}'; then phase=day; elif awk -v a="$altitude" 'BEGIN{exit !(a<=-8)}'; then phase=night; else phase=solar-fade; fi
        else fadeMethod=duration; fi
      else fadeMethod=duration; fi
    fi
    # TV sensor mode reads the model-dependent webOS PQ controller service.
    # If unsupported or stale, use the normal clock schedule instead of failing.
    if [ "$fadeMethod" = tv-sensor ]; then
      if [ "${1:-}" = refresh-sensor ]; then lux=$(tv_sensor_luminance 2>/dev/null || true); else lux=$(cached_tv_sensor_luminance 2>/dev/null || true); fi
      if [ -n "$lux" ]; then
        write_tv_sensor_status 1 "$lux"
        pct=$(awk -v l="$lux" -v c="$curve" 'BEGIN { if(l<0)l=0;if(l>200000)l=200000;lo=log(2);hi=log(501);x=(log(l+1)-lo)/(hi-lo);if(x<0)x=0;if(x>1)x=1;pi=atan2(0,-1);if(c=="easein")x=x*x;else if(c=="easeout")x=1-(1-x)*(1-x);else if(c=="smooth")x=x*x*(3-2*x);else if(c=="smootherstep")x=x*x*x*(x*(x*6-15)+10);else if(c=="twilight")x=0.5-0.5*cos(pi*x);else if(c=="rolloff-soft")x=log(1+4*x)/log(5);else if(c=="rolloff")x=log(1+9*x)/log(10);else if(c=="rolloff-strong")x=log(1+19*x)/log(20);else if(c=="exponential")x=(exp(4*x)-1)/(exp(4)-1);else if(c=="gamma-late")x=x^2.2;else if(c=="gamma-early")x=x^0.4545454545;printf "%d\n",int(x*100+0.5) }')
        brightness=$((min + (max-min)*pct/100)); hdrBrightness=$((hdrMin + (hdrMax-hdrMin)*pct/100)); phase=tv-sensor-response
      else
        write_tv_sensor_status 0 ''
        fadeMethod=duration
      fi
    fi
    # Ambient mode uses the newest illuminance sample. If it goes stale, fall back
    # to the clock schedule instead of holding an old sensor value indefinitely.
    if [ "$fadeMethod" = ambient ]; then
      lux=$haLux
      if [ "$haLuxFresh" = 1 ]; then
        luxMin=${AMBIENT_LUX_MIN:-5}; luxMax=${AMBIENT_LUX_MAX:-500}
        case "$luxMin" in ''|*[!0-9]*) luxMin=5;; esac
        case "$luxMax" in ''|*[!0-9]*) luxMax=500;; esac
        case "$luxMin" in ???????*) luxMin=5;; esac
        case "$luxMax" in ???????*) luxMax=500;; esac
        if [ "$luxMin" -ge "$luxMax" ] 2>/dev/null || [ "$luxMin" -gt 200000 ] 2>/dev/null || [ "$luxMax" -gt 200000 ] 2>/dev/null; then luxMin=5; luxMax=500; fi
        pct=$(awk -v l="$lux" -v low="$luxMin" -v high="$luxMax" -v c="$curve" 'BEGIN { if(l<0)l=0;if(l>200000)l=200000;lo=log(low+1);hi=log(high+1);x=(log(l+1)-lo)/(hi-lo);if(x<0)x=0;if(x>1)x=1;pi=atan2(0,-1);if(c=="easein")x=x*x;else if(c=="easeout")x=1-(1-x)*(1-x);else if(c=="smooth")x=x*x*(3-2*x);else if(c=="smootherstep")x=x*x*x*(x*(x*6-15)+10);else if(c=="twilight")x=0.5-0.5*cos(pi*x);else if(c=="rolloff-soft")x=log(1+4*x)/log(5);else if(c=="rolloff")x=log(1+9*x)/log(10);else if(c=="rolloff-strong")x=log(1+19*x)/log(20);else if(c=="exponential")x=(exp(4*x)-1)/(exp(4)-1);else if(c=="gamma-late")x=x^2.2;else if(c=="gamma-early")x=x^0.4545454545;printf "%d\n",int(x*100+0.5) }')
        brightness=$((min + (max-min)*pct/100)); hdrBrightness=$((hdrMin + (hdrMax-hdrMin)*pct/100)); phase=ambient-response
      else fadeMethod=duration; fi
    fi
    # Time-based mode (also the safe fallback for missing/stale solar or lux data).
    if [ "$fadeMethod" = duration ]; then
      dimElapsed=$(elapsed "$now" "$dimStart"); upElapsed=$(elapsed "$now" "$upStart")
      if [ "$upDur" -gt 0 ] && [ "$upElapsed" -lt "$upDur" ]; then
        pct=$(curve_percent "$upElapsed" "$upDur" "$curve"); brightness=$((min + (max-min)*pct/100)); hdrBrightness=$((hdrMin + (hdrMax-hdrMin)*pct/100)); phase=morning-fade
      elif [ "$dimDur" -gt 0 ] && [ "$dimElapsed" -lt "$dimDur" ]; then
        pct=$(curve_percent "$dimElapsed" "$dimDur" "$curve"); brightness=$((max - (max-min)*pct/100)); hdrBrightness=$((hdrMax - (hdrMax-hdrMin)*pct/100)); phase=evening-fade
      elif in_cyclic_range "$now" "$dimEnd" "$upStart"; then
        brightness=$min; hdrBrightness=$hdrMin; phase=night
      else
        brightness=$max; hdrBrightness=$hdrMax; phase=day
      fi
    fi
  fi
  # Ambient offset shifts the lux-mapped screen and LED targets together.
  if [ "$phase" = ambient-response ]; then
    ambientOffset=${AMBIENT_BRIGHTNESS_OFFSET:-0}; case "$ambientOffset" in ''|*[!0-9-]*) ambientOffset=0;; esac
    [ "$ambientOffset" -lt -30 ] && ambientOffset=-30; [ "$ambientOffset" -gt 30 ] && ambientOffset=30
    brightness=$((brightness + ambientOffset)); [ "$brightness" -lt 0 ] && brightness=0; [ "$brightness" -gt 100 ] && brightness=100
    hdrBrightness=$((hdrBrightness + ambientOffset)); [ "$hdrBrightness" -lt 0 ] && hdrBrightness=0; [ "$hdrBrightness" -gt 100 ] && hdrBrightness=100
  fi
  # Home Assistant's bounded general offset adjusts the TV panel target only.
  offset=${HA_BRIGHTNESS_OFFSET:-0}; case "$offset" in ''|*[!0-9-]*) offset=0;; esac
  [ "$offset" -lt -30 ] && offset=-30; [ "$offset" -gt 30 ] && offset=30
  brightness=$((brightness + offset)); [ "$brightness" -lt 0 ] && brightness=0; [ "$brightness" -gt 100 ] && brightness=100
  eye=off
  eyeLuxDecision=0
  eyeMode=${HA_EYE_COMFORT_OVERRIDE:-dynamic}
  case "$eyeMode" in auto) eyeMode=dynamic;; esac
  if [ "$eyeMode" = dynamic ] && [ "${ENABLED:-1}" = 1 ] && [ ! -f "$ROOT_DIR/override.flag" ] && [ "${EYE_ENABLED:-1}" = 1 ]; then
    eyeLux=$haLux; eyeLuxThreshold=${EYE_LUX_THRESHOLD:-50}
    case "$eyeLuxThreshold" in ''|*[!0-9]*) eyeLuxThreshold=50;; esac
    [ "$eyeLuxThreshold" -le 200000 ] 2>/dev/null || eyeLuxThreshold=50
    luxStability=${LUX_STABILITY:-10}
    case "$luxStability" in ''|*[!0-9]*) luxStability=10;; esac
    [ "$luxStability" -le 1000 ] 2>/dev/null || luxStability=10
    if [ "$haLuxFresh" = 1 ]; then
      lastDynamicEye=$(cat "$ROOT_DIR/eye-lux-state" 2>/dev/null || true)
      if [ "$lastDynamicEye" = on ]; then
        eyeLuxOffThreshold=$((eyeLuxThreshold + luxStability))
        [ "$eyeLux" -le "$eyeLuxOffThreshold" ] && eye=on || eye=off
      else
        [ "$eyeLux" -le "$eyeLuxThreshold" ] && eye=on || eye=off
      fi
      eyeLuxDecision=1
    fi
  fi
  if [ "$eyeLuxDecision" = 0 ] && [ "${ENABLED:-1}" = 1 ] && [ ! -f "$ROOT_DIR/override.flag" ] && [ "${EYE_ENABLED:-1}" = 1 ]; then
    if [ "${EYE_TIMING:-linked}" = custom ]; then
      eyeStart=$(parse_time "${EYE_START:-21:30}"); eyeEnd=$(parse_time "${EYE_END:-06:30}")
    else
      eyeStart=$(norm $((dimStart + ${EYE_START_OFFSET:-15})))
      eyeEnd=$(norm $((upStart + ${EYE_END_OFFSET:-0})))
    fi
    if [ "$eyeStart" -eq "$eyeEnd" ]; then eye=off
    elif in_cyclic_range "$now" "$eyeStart" "$eyeEnd"; then eye=on
    fi
  fi
  case "$eyeMode" in on) eye=on;; off) eye=off;; esac
  printf '%s %s %s %s\n' "$brightness" "$eye" "$phase" "$hdrBrightness"
}
update_eye_lux_state(){
  mode=${HA_EYE_COMFORT_OVERRIDE:-dynamic}; case "$mode" in auto) mode=dynamic;; esac
  if [ "$mode" = dynamic ] && [ "${ENABLED:-1}" = 1 ] && [ ! -f "$ROOT_DIR/override.flag" ] && [ "${EYE_ENABLED:-1}" = 1 ]; then
    lux=${HA_AMBIENT_LUX:-}; stamp=${HA_AMBIENT_LUX_UPDATED:-0}; now=$(date +%s)
    sessionStart=0
    if [ -r "$ROOT_DIR/lux-session-start" ]; then sessionStart=$(cat "$ROOT_DIR/lux-session-start" 2>/dev/null || echo 0); fi
    case "$sessionStart" in ''|*[!0-9]*) sessionStart=0;; esac
    case "$lux" in ''|*[!0-9]*) lux='';; esac
    case "$stamp" in ''|*[!0-9]*) stamp=0;; esac
    if [ -n "$lux" ] && [ "$lux" -le 200000 ] 2>/dev/null && [ "$stamp" -gt "$sessionStart" ] 2>/dev/null && [ $((now-stamp)) -ge 0 ] && [ $((now-stamp)) -le 120 ]; then
      case "$1" in on|off) printf '%s\n' "$1" > "$ROOT_DIR/eye-lux-state.tmp" && chmod 600 "$ROOT_DIR/eye-lux-state.tmp" && mv "$ROOT_DIR/eye-lux-state.tmp" "$ROOT_DIR/eye-lux-state";; esac
    else rm -f "$ROOT_DIR/eye-lux-state" "$ROOT_DIR/eye-lux-state.tmp"; fi
  else rm -f "$ROOT_DIR/eye-lux-state" "$ROOT_DIR/eye-lux-state.tmp"; fi
}
apply_once(){
  values=$(calculate refresh-sensor) || return 1
  set -- $values; brightness=$1; eye=$2; phase=$3; hdrBrightness=${4:-0}
  payload="{\"category\":\"picture\",\"settings\":{\"backlight\":$brightness,\"eyeComfortMode\":\"$eye\"}}"
  apply_rc=0
  if command -v luna-send >/dev/null 2>&1; then
    response=$(luna-send -n 1 -f 'luna://com.webos.settingsservice/setSystemSettings' "$payload" 2>&1); rc=$?
    printf '%s\n' "$response" >> "$LOG"
    if [ "$rc" -ne 0 ]; then result=error; apply_rc=1
    elif printf '%s\n' "$response" | grep -Eq '"returnValue"[[:space:]]*:[[:space:]]*false'; then result=rejected; apply_rc=1
    else result=sent; fi
  else result=no-luna-send; apply_rc=1; fi
  stamp=$(date +%s)
  { printf 'SCREEN_APPLY_STATUS=%s\n' "$result"; printf 'SCREEN_APPLY_BACKLIGHT=%s\n' "$brightness"; printf 'SCREEN_APPLY_UPDATED=%s\n' "$stamp"; } > "$ROOT_DIR/apply-status.tmp" && chmod 600 "$ROOT_DIR/apply-status.tmp" && mv "$ROOT_DIR/apply-status.tmp" "$ROOT_DIR/apply-status"
  update_eye_lux_state "$eye"
  printf '%s\n' "$(date '+%Y-%m-%d %H:%M:%S') phase=$phase backlight=$brightness eyeComfortMode=$eye result=$result" >> "$LOG"
  if [ "${HYPERHDR_ENABLED:-0}" = 1 ] && [ -x "$ROOT_DIR/hyperhdr.sh" ]; then
    if "$ROOT_DIR/hyperhdr.sh" apply "$hdrBrightness" >> "$LOG" 2>&1; then
      hdr_result=sent
    else
      hdr_result=error
      printf '%s HyperHDR apply failed for brightness=%s; panel schedule continues; starting non-blocking startup retry\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$hdrBrightness" >> "$LOG"
      if [ -x "$ROOT_DIR/hyperhdr-retry.sh" ]; then
        nohup "$ROOT_DIR/hyperhdr-retry.sh" >/tmp/panelcomfort-hyperhdr-retry.log 2>&1 &
      fi
    fi
  else hdr_result=skipped; fi
  { printf 'HYPERHDR_APPLY_STATUS=%s\n' "$hdr_result"; printf 'HYPERHDR_APPLY_BRIGHTNESS=%s\n' "$hdrBrightness"; printf 'HYPERHDR_APPLY_UPDATED=%s\n' "$stamp"; } > "$ROOT_DIR/hyperhdr-apply-status.tmp" && chmod 600 "$ROOT_DIR/hyperhdr-apply-status.tmp" && mv "$ROOT_DIR/hyperhdr-apply-status.tmp" "$ROOT_DIR/hyperhdr-apply-status"
  return "$apply_rc"
}
if [ "${1:-}" = --calculate ]; then . "$CFG"; calculate; exit 0; fi
if [ "${1:-}" = --once ]; then
  acquire_apply_lock || exit 1
  trap release_apply_lock 0
  trap 'release_apply_lock; exit 1' HUP INT TERM
  . "$CFG"
  apply_once
  result=$?
  release_apply_lock
  exit "$result"
fi
# Only one daemon: the launcher handles stale pid files and writes the new PID.
while :; do
  if acquire_apply_lock; then
    # Read settings only after taking the lock so a queued request applies the
    # latest complete config, and screen/HyperHDR writes never overlap.
    . "$CFG"
    apply_once || log 'Apply command reported an error'
    release_apply_lock
  else
    log 'Could not acquire the apply lock; will retry next interval'
  fi
  if [ "${ENABLED:-1}" != 1 ]; then exit 0; fi
  # Between full applies, check every 10 s that HyperHDR still holds the LED
  # level. A HyperHDR restart resets it to its saved default (often 100%).
  # The level comes from the last-applied record, so changes made in between
  # (from Home Assistant or the web UI) are never undone.
  step=0
  while [ "$step" -lt 6 ]; do
    sleep 10
    step=$((step + 1))
    [ "${HYPERHDR_ENABLED:-0}" = 1 ] || continue
    watched=$(sed -n 's/^HYPERHDR_APPLY_BRIGHTNESS=//p' "$ROOT_DIR/hyperhdr-apply-status" 2>/dev/null)
    grep -qx 'HYPERHDR_APPLY_STATUS=sent' "$ROOT_DIR/hyperhdr-apply-status" 2>/dev/null || continue
    case "$watched" in ''|*[!0-9]*) continue;; esac
    "$ROOT_DIR/hyperhdr.sh" check "$watched" >/dev/null 2>&1 && continue
    if acquire_apply_lock; then
      if "$ROOT_DIR/hyperhdr.sh" apply "$watched" >> "$LOG" 2>&1; then log "HyperHDR level restored to $watched% after a reset"; fi
      release_apply_lock
    fi
  done
done
